"""The generated files of the repository and the text each one must have.

One place declares which file is derived from which source (R38):

- docs/adr/README.md, from `adrs export json` filtered with `jq`;
- skills/README.md, .claude/skills/<name>/SKILL.md, .claude/rules/<name>.md and
  the routing table of AGENTS.md, from skills/<name>.md (agent_layer.py);
- .claude/agents/<role>.md, from agents/<role>.md;
- .claude/settings.json, from the list of generated files;
- docs/catalog.md, from the model, the registers, the tasks, the tools of
  mise.toml, the workflows, the skills, the roles and the fitness markers of the model;
- tests/pending.toml, from the model's JSON export and the written tests.

`mise run generate` writes them; `mise run generate:check` fails when one is
out of date. Nothing here reads the text of the model: the verifications come
from the Pilot Implementation's export (tests/repository/sysml_model.py).
"""

import os
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "tests" / "repository"))
sys.path.insert(0, str(Path(__file__).resolve().parent))

import agent_layer as al

TASK = "mise run generate"


# ---- ADR index ----------------------------------------------------------


# The only glue between `adrs` and the index (GAP-023): the tool's own table of
# contents has no status. One table row per record, from `adrs export json`.
ADR_ROW = r"""
  .adrs | sort_by(.number)[] | (.path | split("/") | last) as $file
  | "| [\(.number | tostring | ("000" + .)[-4:])](\($file))"
    + " | \(.title | gsub("\\|"; "\\|")) | \(.status | ascii_downcase) |"
"""


def adr_index():
    env = dict(os.environ, ADRS_CONFIG=str(ROOT / "adrs.toml"))
    exported = subprocess.run(
        ["adrs", "export", "json"],
        cwd=ROOT,
        env=env,
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    rows = subprocess.run(
        ["jq", "-r", ADR_ROW],
        input=exported,
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    return (
        f"<!-- Generated by `{TASK}` from the ADR files. Do not edit. -->\n\n"
        "# Architecture decision records\n\n"
        "An ADR records a decision, with its context and consequences. What is built\n"
        "and verified today is told by the tests and by `tests/pending.toml`, which\n"
        "lists the verifications whose test is not written yet; an ADR in the status\n"
        '"proposed" describes the intended system, not the present one.\n\n'
        "| ADR | Title | Status |\n"
        "| --- | ----- | ------ |\n" + rows
    )


# ---- tests/pending.toml -------------------------------------------------


def _order(name):
    """By what the test is about, not by id: new verifications take the next id,
    so by id every branch that adds one inserts at the end and they conflict (R150)."""
    return re.sub(r"^test_R\d+(?:_\d+(?=_))?_", "", name), name


def render_pending(verifications, tests):
    """The verifications of the model that have no written test."""
    pending = sorted(set(verifications) - set(tests), key=_order)
    items = "".join(f'  "{name}",\n' for name in pending)
    body = f"pending = [\n{items}]\n" if pending else "pending = []\n"
    return (
        f"# Generated by `{TASK}`. Do not edit.\n"
        "#\n"
        "# Verifications in model/anima.sysml whose test is not written yet,\n"
        "# computed from the model's JSON export and the names of the tests.\n"
        "#\n"
        "# This list shrinks as tests are written; it grows only when a requirement\n"
        "# is added to the model. tests/repository/test_traceability.py fails when a\n"
        "# verification is neither tested nor listed here, and when a test listed\n"
        "# here has been written. Version 0.0.1 is released with this list empty.\n"
        + body
    )


def pending_toml(model=None):
    import sysml_model  # imported here: the export is slow, so only when needed

    model = model or sysml_model.export_model()
    return render_pending(
        sysml_model.verifications(model), sysml_model.names_of_tests()
    )


# ---- The list of fitness functions in the catalog ------------------------------------------

TRIGGER_TEXT = {
    "commit": "at every commit",
    "promotion": "when an image is promoted",
    "runtime": "against the running system",
}


def fitness_list(model, tests):
    """One line per requirement marked `@FitnessFunction` in the model: its id,
    its name, when it runs, and its test (written or pending)."""
    return render_fitness(fitness_entries(model, tests))


def fitness_entries(model, tests):
    """(id, name, trigger text, test, state) of each marked requirement."""
    import sysml_model

    markers = sysml_model.fitness_functions(model)
    by_name = {
        e["declaredShortName"]: e
        for e in model.values()
        if sysml_model.is_requirement(model, e)
    }
    verifications = sysml_model.verifications(model)
    entries = []
    for short in markers:
        requirement = by_name[short]
        words = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", requirement["declaredName"]).lower()
        names = sorted(
            n for n, targets in verifications.items() if requirement["@id"] in targets
        )
        test = names[0] if names else "no verification"
        state = "written" if test in tests else "pending"
        entries.append((short, words, TRIGGER_TEXT[markers[short]], test, state))
    return entries


def render_fitness(entries):
    """By name, then id, for the reason given at `_order` (R150)."""
    ordered = sorted(
        entries, key=lambda e: (e[1], [int(n) for n in re.findall(r"\d+", e[0])])
    )
    return "\n".join(
        f"- {short}, {words}, {trigger}: `{test}` ({state})."
        for short, words, trigger, test, state in ordered
    )


# ---- All of them --------------------------------------------------------

AGENTS_MD = "AGENTS.md"
# Written whole by the generator: an agent may not edit them (R86). AGENTS.md
# is only partly generated (its routing table), so it stays editable.
WHOLLY_GENERATED = [
    "docs/adr/README.md",
    "skills/README.md",
    "tests/pending.toml",
    "docs/catalog.md",
    ".claude/settings.json",
]


def wholly_generated():
    """Paths of the files the generator writes whole: the one source that the
    agent settings and the stale check share (`mise run generate:list`)."""
    paths = list(WHOLLY_GENERATED)
    paths += [f".claude/skills/{s.name}/SKILL.md" for s in al.skills()]
    paths += [f".claude/rules/{s.name}.md" for s in al.skills() if s.paths]
    paths += [f".claude/agents/{r.name}.md" for r in al.roles()]
    return sorted(paths)


def outputs():
    """Every generated file: path relative to the root, and its exact text."""
    import sysml_model

    model = sysml_model.export_model()
    tests = sysml_model.names_of_tests()
    all_skills = al.skills()
    all_roles = al.roles()
    components = load_components()
    tasks = al.task_descriptions()
    files = {
        "docs/adr/README.md": adr_index(),
        "skills/README.md": al.skills_index(all_skills, al.not_yet_present()),
        "tests/pending.toml": pending_toml(model),
        "docs/catalog.md": al.catalog(
            model,
            tests,
            all_skills,
            all_roles,
            components,
            tasks,
            al.synonyms(),
            fitness_list(model, tests),
        ),
        AGENTS_MD: al.agents_md((ROOT / AGENTS_MD).read_text(), all_skills),
    }
    for skill in all_skills:
        files[f".claude/skills/{skill.name}/SKILL.md"] = al.skill_pointer(skill)
        if skill.paths:
            files[f".claude/rules/{skill.name}.md"] = al.rule_file(skill)
    for role in all_roles:
        files[f".claude/agents/{role.name}.md"] = al.vendor_role(role)
    files[".claude/settings.json"] = al.settings_json(wholly_generated())
    assert set(wholly_generated()) <= set(files), "a wholly generated file is missing"
    return files


def load_components():
    import tomllib

    return tomllib.loads((ROOT / "components.toml").read_text())["component"]


ORPHAN_DIRECTORIES = [".claude/skills", ".claude/rules", ".claude/agents"]


def stale(files, root=ROOT):
    """Names of the files that are missing under `root`, differ from their text,
    or sit in a generated directory without being generated any more."""
    found = [
        name
        for name, text in files.items()
        if not (root / name).exists() or (root / name).read_text() != text
    ]
    for directory in ORPHAN_DIRECTORIES:
        if (root / directory).is_dir():
            found += [
                str(p.relative_to(root))
                for p in sorted((root / directory).rglob("*"))
                if p.is_file() and str(p.relative_to(root)) not in files
            ]
    return found
